const description: { en: string; ja: string } = {"en":"A notched front petal overlaps two wide side petals. A forked twig bends beneath them to a pointed leaf with short diagonal veins.","ja":"先の割れた正面の花弁に、左右の広い花弁が重なります。その下で枝が二つに分かれ、先のとがった葉には斜めの短い葉脈を入れます。"};

export default construction;
